package Day02;

public class AssignmentOperators {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int number = 10;
		
		number += 5;
		System.out.println("value of number is " + number);
		
		number -= 5;
		System.out.println("value of number is " + number);
		
		number *= 5;
		System.out.println("value of number is " + number);

		number /= 5;
		System.out.println("value of number is " + number);

	}

}
